begin;
insert into auth.users(id) values('a5555555-5555-4555-8555-555555555555'),('b5555555-5555-4555-8555-555555555555');
select set_config('request.jwt.claims','{"sub":"a5555555-5555-4555-8555-555555555555"}',true);
select public.kiyi_command('bundle');
update public.kiyi_wallets set balance=3000 where user_id='a5555555-5555-4555-8555-555555555555';
set local role authenticated;
do $$declare x jsonb;y jsonb;id uuid;bid uuid;denied boolean;v int;begin
 x=public.kiyi_command('vehicle_create','{"model":"peugeot-208","plate":"07 MULTI 101"}');id=(x->>'id')::uuid;
 x=public.kiyi_command('vehicle_create','{"model":"honda-pcx-125","plate":"07 MULTI 102"}');bid=(x->>'id')::uuid;
 x=public.kiyi_command('garage_list');assert jsonb_array_length(x->'vehicles')=3,'Missing vehicles';
 perform public.kiyi_command('appearance',jsonb_build_object('vehicle_id',id,'kind','color','value','#aa55ff','request_id',gen_random_uuid()));
 x=public.kiyi_command('garage_list');assert exists(select 1 from jsonb_array_elements(x->'vehicles')r where r->>'id'=id::text and r->'appearance'->>'paint'='#aa55ff'),'Color missing';
 y=public.kiyi_command('bundle');assert y->'me'->>'paint'='#ffffff','Secondary color leaked';
 select (r->>'version')::int into v from jsonb_array_elements(x->'vehicles')r where r->>'id'=id::text;
 perform public.kiyi_command('vehicle_customize',jsonb_build_object('vehicle_id',id,'version',v,'appearance','{"wrap":"milk-wave","rim":"sport-red","accessories":{"headlights":"head-ice","roof":"roof-bow"}}'::jsonb));
 denied=false;begin perform public.kiyi_command('vehicle_customize',jsonb_build_object('vehicle_id',id,'version',v,'appearance','{"rim":"sport-red"}'::jsonb));exception when serialization_failure then denied=true;end;assert denied,'Stale update accepted';
 denied=false;begin perform public.kiyi_command('vehicle_customize',jsonb_build_object('vehicle_id',bid,'version',1,'appearance','{"rim":"sport-red"}'::jsonb));exception when invalid_parameter_value then denied=true;end;assert denied,'Unready bike customization accepted';
 perform set_config('request.jwt.claims','{"sub":"b5555555-5555-4555-8555-555555555555"}',true);
 x=public.kiyi_command('garage_list');assert jsonb_array_length(x->'vehicles')=1,'Other user garage leaked';
 denied=false;begin perform public.kiyi_command('appearance',jsonb_build_object('vehicle_id',id,'kind','color','value','#ffffff'));exception when insufficient_privilege then denied=true;end;assert denied,'Cross user customization allowed';
 denied=false;begin perform public.kiyi_command('profile','{"profile":{"plate":"07 MULTI 101"}}');exception when unique_violation then denied=true;end;assert denied,'Secondary plate stolen';
 denied=false;begin perform public.kiyi_media_worker('reserve','{}');exception when insufficient_privilege then denied=true;end;assert denied,'Client called media worker';
 denied=false;begin perform 1 from public.kiyi_vehicle_customizations;exception when insufficient_privilege then denied=true;end;assert denied,'Direct garage read permitted';
end$$;
reset role;
do $$declare x jsonb;denied boolean;begin
 denied=false;begin perform public.kiyi_media_worker('reserve','{"owner":"a5555555-5555-4555-8555-555555555555","mime":"image/svg+xml","bytes":200}');exception when raise_exception then denied=true;end;assert denied,'SVG accepted';
 denied=false;begin perform public.kiyi_media_worker('reserve','{"owner":"a5555555-5555-4555-8555-555555555555","mime":"image/png","bytes":5242881}');exception when raise_exception then denied=true;end;assert denied,'Oversize image accepted';
 denied=false;begin perform public.kiyi_media_worker('reserve','{"owner":"a5555555-5555-4555-8555-555555555555","mime":"video/mp4","bytes":20971521}');exception when raise_exception then denied=true;end;assert denied,'Oversize video accepted';
 x=public.kiyi_media_worker('reserve','{"owner":"a5555555-5555-4555-8555-555555555555","mime":"video/mp4","bytes":20971520}');assert x?'path','Valid video reservation failed';
 denied=false;begin perform public.kiyi_media_worker('cleanup','{"secret":"invalid"}');exception when insufficient_privilege then denied=true;end;assert denied,'Unauthenticated cleanup allowed';
end$$;
do $$declare x jsonb;p text;pid uuid;paths jsonb;denied boolean;begin
 x=public.kiyi_media_worker('reserve','{"owner":"a5555555-5555-4555-8555-555555555555","mime":"image/png","bytes":24}');p=x->>'path';
 insert into storage.objects(bucket_id,name,metadata) values('kiyi-media',p,'{"size":24,"mimetype":"image/png"}');
 perform public.kiyi_media_worker('confirm',jsonb_build_object('path',p));
 perform set_config('request.jwt.claims','{"sub":"a5555555-5555-4555-8555-555555555555"}',true);
 x=public.kiyi_command('post_create',jsonb_build_object('text','Medya testi','visibility','followers','media',p));pid=(x->'post'->>'id')::uuid;
 update kiyi_private.media_registry set created_at=now()-interval '48 hours' where path=p;
 paths=public.kiyi_media_worker('cleanup',jsonb_build_object('secret',(select secret from kiyi_private.media_worker_secret)));
 assert not(paths->'paths'?p),'Referenced media queued';
 perform public.kiyi_command('post_delete',jsonb_build_object('id',pid));
 paths=public.kiyi_media_worker('cleanup',jsonb_build_object('secret',(select secret from kiyi_private.media_worker_secret)));
 assert paths->'paths'?p,'Deleted media not queued';
 denied=false;begin perform public.kiyi_media_worker('ack',jsonb_build_object('path',p));exception when raise_exception then denied=true;end;assert denied,'Ack accepted before Storage API deletion';
 x=public.kiyi_media_worker('reserve','{"owner":"a5555555-5555-4555-8555-555555555555","mime":"image/png","bytes":24}');p=x->>'path';
 update kiyi_private.media_registry set state='deleting' where path=p;
 perform public.kiyi_media_worker('ack',jsonb_build_object('path',p));
 assert not exists(select 1 from kiyi_private.media_registry where path=p),'Cleanup registry retained';
end$$;
select 'PASS: two-user garage isolation, paid color isolation, parts, stale writes, inactive bikes, plate uniqueness, privileged media, format/size bounds' as result;
rollback;
